export function calcularTotal(precio, cantidad) {
  if (precio < 0 || cantidad < 0) throw new Error('Valores inválidos');
  return precio * cantidad;
}

// Prueba conceptual
console.assert(calcularTotal(100, 3) === 300);

import { describe, expect, it } from 'vitest';

function calcularTotal(precios) {
  return precios.reduce((total, precio) => total + precio, 0);
}

describe('calcularTotal', () => {
  it('suma los precios', () => {
    expect(calcularTotal([10, 15, 20])).toBe(45);
  });

  it('devuelve cero para una lista vacía', () => {
    expect(calcularTotal([])).toBe(0);
  });
});

